export declare const easternNotesTheme = "/* \u4E1C\u65B9\u7B3A\u8C31\uFF1A\u73B0\u4EE3\u4EBA\u6587\u957F\u6587 */\n#wemd {\n  max-width: 677px;\n  margin: 0 auto;\n  padding: 24px 28px;\n  color: #36322f;\n  background-color: transparent;\n  font-family: \"Songti SC\", \"STSong\", \"Noto Serif CJK SC\", SimSun, serif;\n  font-size: 17px;\n  line-height: 2.06;\n  letter-spacing: 0.045em;\n  word-break: break-word;\n}\n\n#wemd p {\n  margin: 0 0 29px;\n  color: #36322f;\n  font-size: 17px;\n  line-height: 2.06;\n  text-align: justify;\n  text-wrap: pretty;\n}\n\n#wemd h1,\n#wemd h2,\n#wemd h3,\n#wemd h4,\n#wemd h5,\n#wemd h6 {\n  text-align: left;\n}\n\n#wemd h1 {\n  max-width: 7em;\n  margin: 38px 0 72px auto;\n  padding: 0 8px 0 0;\n  border: none;\n  text-align: right;\n}\n\n#wemd h1::after {\n  content: \"\";\n  display: block;\n  width: 18px;\n  height: 18px;\n  margin: 24px 0 0 auto;\n  background: #a33a2b;\n}\n\n#wemd h1 .content {\n  display: inline-block;\n  max-width: 100%;\n  color: #282522;\n  font-size: 32px;\n  font-weight: 700;\n  line-height: 1.5;\n  letter-spacing: 0.18em;\n  text-wrap: balance;\n}\n\n#wemd h2 {\n  margin: 58px 0 30px;\n  padding: 0 8px 0 0;\n  border: none;\n  text-align: right;\n}\n\n#wemd h2::before {\n  content: \"\u25C6\";\n  display: block;\n  margin-bottom: 8px;\n  color: #a33a2b;\n  font-size: 9px;\n  text-align: right;\n}\n\n#wemd h2 .content {\n  color: #a33a2b;\n  font-size: 21px;\n  font-weight: 700;\n  letter-spacing: 0.12em;\n  text-wrap: balance;\n}\n\n#wemd h3 {\n  margin: 40px 0 21px 2em;\n}\n\n#wemd h3 .content {\n  display: inline;\n  padding: 0;\n  color: #a33a2b;\n  background: transparent;\n  font-size: 18px;\n  font-weight: 700;\n  line-height: 1.6;\n  letter-spacing: 0.1em;\n  text-wrap: balance;\n}\n\n#wemd h4,\n#wemd h5,\n#wemd h6 {\n  margin: 29px 0 14px;\n  padding: 0;\n  border: none;\n}\n\n#wemd h4 .content,\n#wemd h5 .content,\n#wemd h6 .content {\n  color: #514841;\n  font-size: 16px;\n  font-weight: 700;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix,\n#wemd h2 .prefix,\n#wemd h2 .suffix,\n#wemd h3 .prefix,\n#wemd h3 .suffix,\n#wemd h4 .prefix,\n#wemd h4 .suffix,\n#wemd h5 .prefix,\n#wemd h5 .suffix,\n#wemd h6 .prefix,\n#wemd h6 .suffix {\n  display: none;\n}\n\n#wemd blockquote {\n  border: none;\n}\n\n#wemd .multiquote-1,\n#wemd .multiquote-2,\n#wemd .multiquote-3 {\n  margin: 46px 8px;\n  padding: 8px 24px;\n  border: none;\n  background: transparent;\n}\n\n#wemd .multiquote-1::before {\n  content: \"\u201C\";\n  display: block;\n  color: #a33a2b;\n  font-size: 42px;\n  line-height: 0.8;\n  text-align: center;\n}\n\n#wemd .multiquote-1 p,\n#wemd .multiquote-2 p,\n#wemd .multiquote-3 p {\n  margin: 0;\n  color: #564c45;\n  font-size: 18px;\n  line-height: 2;\n  text-align: center;\n}\n\n#wemd .multiquote-2,\n#wemd .multiquote-3,\n#wemd .multiquote-1 .multiquote-1 {\n  margin: 12px 0 0;\n  padding: 8px 0 0;\n  border: none;\n}\n\n#wemd .multiquote-1 .multiquote-1::before {\n  display: none;\n}\n\n#wemd ul,\n#wemd ol {\n  margin: 22px 0 28px;\n  padding-left: 25px;\n  color: #a33a2b;\n}\n\n#wemd li section {\n  margin: 7px 0;\n  color: #36322f;\n  line-height: 1.88;\n}\n\n#wemd ol > li > section {\n  padding: 3px 0 9px;\n  border: none;\n  border-bottom: 1px dotted #bfb4aa;\n  background: transparent;\n}\n\n#wemd a {\n  color: #8c3025;\n  font-weight: 600;\n  text-decoration: underline;\n  text-decoration-color: #c99087;\n  text-underline-offset: 0.22em;\n}\n\n#wemd strong {\n  color: #272320;\n  font-weight: 700;\n  text-decoration: underline;\n  text-decoration-color: #d9aaa2;\n  text-decoration-thickness: 2px;\n  text-underline-offset: 0.18em;\n}\n\n#wemd mark {\n  padding: 1px 4px;\n  color: #4f2822;\n  background: #efd9d4;\n}\n\n#wemd hr {\n  width: 8px;\n  height: 8px;\n  margin: 64px auto;\n  border: none;\n  background: #a33a2b;\n}\n\n#wemd figure {\n  margin: 48px 0 54px;\n  padding: 0;\n  border: none;\n  break-inside: avoid;\n}\n\n#wemd figure a {\n  border: none;\n}\n\n#wemd img,\n#wemd figure a img {\n  display: block;\n  max-width: 100%;\n  height: auto;\n  margin: 0 auto;\n}\n\n#wemd figcaption {\n  margin-top: 12px;\n  color: #746860;\n  font-size: 12px;\n  line-height: 1.8;\n  letter-spacing: 0.08em;\n  text-align: right;\n}\n\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n  padding: 2px 6px;\n  border: 1px solid #d4cbc3;\n  color: #8c3025;\n  background: #f1eeea;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 13px;\n}\n\n#wemd pre {\n  margin: 32px 0;\n  border: 1px solid #403a35;\n  border-top: 6px solid #a33a2b;\n  background: #2e2a27;\n  overflow-x: auto;\n}\n\n#wemd pre code,\n#wemd pre code.hljs {\n  display: block;\n  min-width: max-content;\n  padding: 20px;\n  color: #f0ece7;\n  background: #2e2a27;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 13px;\n  line-height: 1.72;\n  white-space: pre;\n}\n\n#wemd pre.custom > .mac-sign {\n  display: block;\n  border-bottom: 1px solid #5d554e;\n  background: #2e2a27;\n}\n\n#wemd .table-container {\n  margin: 34px 0;\n  overflow-x: auto;\n}\n\n#wemd table {\n  width: 100%;\n  border-collapse: collapse;\n  color: #3d3732;\n  background: #faf9f7;\n  text-align: left;\n}\n\n#wemd table tr th,\n#wemd table tr td {\n  min-width: 88px;\n  padding: 11px 10px;\n  border: none;\n  border-bottom: 1px solid #cfc6be;\n  font-size: 14px;\n  line-height: 1.65;\n}\n\n#wemd table tr th {\n  border-top: 1px solid #5a4e46;\n  border-bottom: 2px solid #5a4e46;\n  color: #a33a2b;\n  background: transparent;\n  font-weight: 700;\n}\n\n#wemd table tr:nth-child(2n) {\n  background: #f0ede9;\n}\n\n#wemd .callout {\n  margin: 31px 0;\n  padding: 18px 4px;\n  border: none;\n  border-top: 1px dotted #8f8177;\n  border-bottom: 1px dotted #8f8177;\n  border-radius: 0;\n  color: #4a423c;\n  background: transparent;\n  break-inside: avoid;\n}\n\n#wemd .callout-warning,\n#wemd .callout-caution {\n  border-color: #a33a2b;\n  background: transparent;\n}\n\n#wemd .callout-title {\n  margin-bottom: 8px;\n  color: #5a2d26;\n  font-weight: 700;\n}\n\n#wemd .callout p {\n  margin: 0;\n  color: #564c45;\n  font-size: 15px;\n}\n\n#wemd .footnote-word,\n#wemd .footnote-ref {\n  color: #a33a2b;\n  font-weight: 700;\n}\n\n#wemd .footnotes-sep {\n  margin-top: 52px;\n  padding-top: 18px;\n  border-top: 4px double #4c4640;\n}\n\n#wemd .footnote-item {\n  display: flex;\n  margin-top: 9px;\n}\n\n#wemd .footnote-num {\n  width: 30px;\n  flex-shrink: 0;\n  color: #a33a2b;\n}\n\n#wemd .footnote-item p {\n  margin: 0;\n  color: #746860;\n  font-size: 13px;\n  text-align: left;\n}\n\n#wemd .block-equation {\n  display: block;\n  margin: 32px 0;\n  padding: 19px 10px;\n  border-top: 1px solid #cfc6be;\n  border-bottom: 1px solid #cfc6be;\n  text-align: center;\n  overflow-x: auto;\n}\n\n#wemd .block-equation > svg {\n  max-width: 300% !important;\n}\n\n#wemd .inline-equation > svg {\n  vertical-align: middle;\n}\n\n#wemd pre.mermaid {\n  padding: 20px 10px;\n  border: 1px solid #c2b7ae;\n  border-top: 5px solid #a33a2b;\n  background: #faf9f7;\n}\n\n#wemd .task-list-item {\n  display: flex;\n  align-items: flex-start;\n  margin-left: -1.2em;\n  list-style: none;\n}\n\n#wemd .task-list-item input[type='checkbox'] {\n  margin-top: 8px;\n  margin-right: 8px;\n  accent-color: #a33a2b;\n  pointer-events: none;\n}\n";
